class MessageQueue
  include MonitorMixin              # synchronize + reentrancy
  def initialize(cap)
    super(); @cap, @q = cap, []; @not_full, @not_empty = new_cond, new_cond
  end
  def put(item)
    synchronize do
      @not_full.wait while @q.size >= @cap   # predicate loop
      @q << item
      @not_empty.signal
    end
  end
end
